//        A
//      /   \
//     B     C
//    / \     \
//   D   E     F

var wurzel = new Knoten('A');
wurzel.Links = new Knoten('B');
wurzel.Rechts = new Knoten('C');
wurzel.Links.Links = new Knoten('D');
wurzel.Links.Rechts = new Knoten('E');
wurzel.Rechts.Rechts = new Knoten('F');

class Knoten
{
    public char Wert;
    public Knoten? Links, Rechts;
    public Knoten(char w) => Wert = w;
}

static void Preorder(Knoten? k)
{
    if (k == null) return;
    Console.Write(k.Wert);  // W
    Preorder(k.Links);      // L
    Preorder(k.Rechts);     // R
}

static void Inorder(Knoten? k)
{
    if (k == null) return;
    Inorder(k.Links);       // L
    Console.Write(k.Wert);  // W
    Inorder(k.Rechts);      // R
}

static void Postorder(Knoten? k)
{
    if (k == null) return;
    Postorder(k.Links);     // L
    Postorder(k.Rechts);    // R
    Console.Write(k.Wert);  // W
}

Preorder(wurzel);  Console.WriteLine();
Inorder(wurzel);   Console.WriteLine();
Postorder(wurzel); Console.WriteLine();
// Ausgabe:
// ABDECF
// DBEACF
// DEBFCA

static void Ebenen(Knoten wurzel)
{
    var q = new Queue<Knoten>();
    q.Enqueue(wurzel);
    while (q.Count > 0)
    {
        Knoten k = q.Dequeue();
        Console.Write(k.Wert);
        if (k.Links != null)
            q.Enqueue(k.Links);
        if (k.Rechts != null)
            q.Enqueue(k.Rechts);
    }
}

static int Hoehe(Knoten? k)
{
    if (k == null) return -1;
    return 1 + Math.Max(Hoehe(k.Links),
                        Hoehe(k.Rechts));
}

Ebenen(wurzel);
Console.WriteLine();
Console.WriteLine(Hoehe(wurzel));
// Ausgabe:
// ABCDEF
// 2

